function UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc)
    --local sBaseOrder = 'Clear'
    --if oUnit[reftiLastOrders] then
        --sBaseOrder = (oUnit[reftiLastOrders][oUnit[refiOrderCount]][subrefiOrderType] or 'Unknown')
    --end
    local sExtraOrder = ''
    if sOptionalOrderDesc then sExtraOrder = ' '..sOptionalOrderDesc end
    local sPlateauAndZoneDesc = ''
    if EntityCategoryContains(categories.LAND + categories.NAVAL, oUnit.UnitId) then
        local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(oUnit:GetPosition())
        sPlateauAndZoneDesc = 'P'..(iPlateauOrZero or 0)..'Z'..(iLandOrWaterZone or 0)
    end
    if AiBotConfig.AiBotShowUnitNames then --redundancy
        if not(AiBotUtilities.bFAFActive) and oUnit:GetAIBrain().AiBotAI then
            --Be clear which units belong to AiBot if not playing in FAF
            oUnit:SetCustomName((oUnit.UnitId or oUnit:GetBlueprint().BlueprintId)..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..sPlateauAndZoneDesc..sExtraOrder)
        else
            oUnit:SetCustomName((oUnit.UnitId or oUnit:GetBlueprint().BlueprintId)..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..sPlateauAndZoneDesc..sExtraOrder)
        end
    end
end

function IssueTrackedClearCommands(oUnit)
    --Update tracking for repairing units:
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        if oUnit[reftiLastOrders] then
            local tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            if tLastOrder[subrefiOrderType] == refiOrderIssueRepair then
                if AiBotUnitInfo.IsUnitValid(tLastOrder[subrefoOrderUnitTarget]) and AiBotUtilities.IsTableEmpty(tLastOrder[subrefoOrderUnitTarget][toUnitsOrderedToRepairThis]) == false then
                    local iRefToRemove
                    for iRepairer, oRepairer in tLastOrder[subrefoOrderUnitTarget][toUnitsOrderedToRepairThis] do
                        if oRepairer == oUnit then
                            iRefToRemove = iRepairer
                            break
                        end
                    end
                    if iRefToRemove then table.remove(tLastOrder[subrefoOrderUnitTarget][toUnitsOrderedToRepairThis], iRefToRemove) end
                end
            elseif tLastOrder[subrefiOrderType] == refiOrderIssueGuard then
                if AiBotUnitInfo.IsUnitValid(tLastOrder[subrefoOrderUnitTarget]) and AiBotUtilities.IsTableEmpty(tLastOrder[subrefoOrderUnitTarget][AiBotUnitInfo.reftoUnitsAssistingThis]) == false then
                    local iRefToRemove
                    for iAssister, oAssister in tLastOrder[subrefoOrderUnitTarget][AiBotUnitInfo.reftoUnitsAssistingThis] do
                        if oAssister == oUnit then
                            iRefToRemove = iAssister
                            break
                        end
                    end
                    if iRefToRemove then
                        table.remove(tLastOrder[subrefoOrderUnitTarget][AiBotUnitInfo.reftoUnitsAssistingThis], iRefToRemove)
                        --LOG('Just cleared unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' from being recorded as assistin unit '..tLastOrder[subrefoOrderUnitTarget].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(tLastOrder[subrefoOrderUnitTarget]))
                    end
                end
            end
        end
        oUnit[reftiLastOrders] = nil
        oUnit[refiOrderCount] = 0
        if oUnit[reftMoveDestinationIgnoredDueToMicro] then oUnit[reftMoveDestinationIgnoredDueToMicro] = nil end
        if oUnit[AiBotEngineer.reftUnitsWeAreReclaiming] and AiBotUtilities.IsTableEmpty(oUnit[AiBotEngineer.reftUnitsWeAreReclaiming]) == false then
            for iUnitBeingReclaimed, oUnitBeingReclaimed in oUnit[AiBotEngineer.reftUnitsWeAreReclaiming] do
                if oUnitBeingReclaimed.UnitId and AiBotUtilities.IsTableEmpty(oUnitBeingReclaimed[AiBotEngineer.reftUnitsReclaimingUs]) == false then
                    for iReclaimer, oReclaimer in oUnitBeingReclaimed[AiBotEngineer.reftUnitsReclaimingUs] do
                        if oReclaimer == oUnit then
                            table.remove(oUnitBeingReclaimed[AiBotEngineer.reftUnitsReclaimingUs], iReclaimer)
                            break
                        end
                    end
                end
            end
            oUnit[AiBotEngineer.reftUnitsWeAreReclaiming] = nil
        end

        --Update tracking for engineers (and clear any assisting engineers via ClearEngineerTracking)
        if EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer + categories.COMMAND + categories.SUBCOMMANDER, oUnit.UnitId) then
            --Dont clear active shield engineers since they can be given different orders (resulting in a clear commands being sent)
            if not(oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionSpecialShieldDefence) and not(oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionManageGameEnderTemplate) then
                AiBotEngineer.ClearEngineerTracking(oUnit) --note - will also clear if try assigning action to engineer that is different to its currently assigned action as part of the track engineer action function, which covers cases where we dont trigger this such as shield special defence
            end
            --Unpause engineers who are about to be cleared
            if oUnit[AiBotUnitInfo.refbPaused] then
                AiBotUnitInfo.PauseOrUnpauseEnergyUsage(oUnit, false)
            end
        end

        --Clear any micro flag if it is time
        if oUnit[AiBotUnitInfo.refbSpecialMicroActive] then
            if GetGameTimeSeconds() + 0.02 > oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] then
                oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] = nil
            end
        end

        --Bomber damage tracking
        if oUnit[AiBotAir.refoStrikeDamageAssigned] then
            AiBotAir.RemoveAssignedAttacker(oUnit[AiBotAir.refoStrikeDamageAssigned], oUnit)
        end

        --AirAA tracking
        if oUnit[AiBotAir.refoAirAACurTarget] then oUnit[AiBotAir.refoAirAACurTarget] = nil end

        --Clear orders:

        if oUnit.UnitId == 'xsl0001' and oUnit:IsUnitState('Teleporting') then AiBotUtilities.ErrorHandler('Are canceling teleport on a teleporting unit') end
        --[[if GetGameTimeSeconds() >= 16*60 and oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'uea010415' then
            LOG('TEMPCODE Just about to issuedclearcommands to unit'..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time '..GetGameTimeSeconds()..'; Unit state before clearing='..AiBotUnitInfo.GetUnitState(oUnit))
            AiBotUtilities.ErrorHandler('Audit trail clear', true, true)
        end--]]

        IssueClearCommands({oUnit})




        --Unit name
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit) end
        --if oUnit.UnitId == 'xel0305' then LOG('Just cleared orders for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time '..GetGameTimeSeconds()) end
    end
end

function RefreshUnitOrderTracking()  end --Just used to easily find UpdateRecordedOrders
function UpdateRecordedOrders(oUnit)
    --Checks a unit's command queue and removes items if we have fewer items than we recorded
    --Also acts as a bcakup for special micro not resetting
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        if oUnit[AiBotUnitInfo.refbSpecialMicroActive] and (oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] or 0) > 0 and GetGameTimeSeconds() > oUnit[AiBotUnitInfo.refiGameTimeToResetMicroActive] then
            oUnit[AiBotUnitInfo.refbSpecialMicroActive] = false
        end
        if not(oUnit[reftiLastOrders]) then
            oUnit[reftiLastOrders] = nil
            oUnit[refiOrderCount] = 0
        else
            if (oUnit[refiOrderCount] or 0) == 0 then
                oUnit[refiOrderCount] = table.getn(oUnit[reftiLastOrders])
            end
            local tCommandQueue
            if oUnit.GetCommandQueue and AiBotUnitInfo.IsUnitValid(oUnit) then
                tCommandQueue = oUnit:GetCommandQueue()
            end
            local iCommandQueue = 0
            if tCommandQueue then iCommandQueue = table.getn(tCommandQueue) end
            if iCommandQueue < oUnit[refiOrderCount] then
                if iCommandQueue == 0 then
                    oUnit[reftiLastOrders] = nil
                    oUnit[refiOrderCount] = 0
                else
                    local iRevisedIndex = 1
                    local iTableSize = oUnit[refiOrderCount]
                    local iOrdersToRemove = oUnit[refiOrderCount] - iCommandQueue

                    for iOrigIndex=1, iTableSize do
                        if oUnit[reftiLastOrders][iOrigIndex] then
                            if iOrigIndex > iOrdersToRemove then
                                --We want to keep the entry; Move the original index to be the revised index number (so if e.g. a table of 1,2,3 removed 2, then this would've resulted in the revised index being 2 (i.e. it starts at 1, then icnreases by 1 for the first valid entry); this then means we change the table index for orig index 3 to be 2
                                if (iOrigIndex ~= iRevisedIndex) then
                                    oUnit[reftiLastOrders][iRevisedIndex] = oUnit[reftiLastOrders][iOrigIndex]
                                    oUnit[reftiLastOrders][iOrigIndex] = nil
                                end
                                iRevisedIndex = iRevisedIndex + 1 --i.e. this will be the position of where the next value that we keep will be located
                            else
                                oUnit[reftiLastOrders][iOrigIndex] = nil
                                oUnit[refiOrderCount] = oUnit[refiOrderCount] - 1
                            end
                        end
                    end
                    if iRevisedIndex < iTableSize then
                        --table.setn(oUnit[reftiLastOrders], iRevisedIndex - 1)
                        for iRemovalEntry = iTableSize, iRevisedIndex, -1 do
                            table.remove(oUnit[reftiLastOrders], iRemovalEntry)
                        end
                    end
                end
            end
        end
    end
    --[[if oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'uea020415' then
        LOG('Just updated orders for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; reprs of last orders='..reprs(oUnit[reftiLastOrders])..'; Is command queue empty='..tostring(AiBotUtilities.IsTableEmpty(oUnit:GetCommandQueue())))
        local tCommandQueue = oUnit:GetCommandQueue()
        for iEntry, tCommand in tCommandQueue do --havent actually tested this bit out
            LOG('reprs of iEntry='..iEntry..'='..reprs(tCommand)) --if this works, then see if https://github.com/FAForever/fa/blob/86d57d438b287d91a7fc6e92e0ab3ce94dc382ce/lua/SimCallbacks.lua#L355 helps make sense of this
        end
    end--]]
end

function IssueTrackedMove(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --If we are close enough then issue the order again - consider the first order given if not to add to existing queue
        local tLastOrder

        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end
        --if oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'uec00011' then LOG('IssueTrackedMove: Time='..GetGameTimeSeconds()..'; reprs of tLastOrder='..reprs(tLastOrder)..'; tOrderPosition='..repru(tOrderPosition)..'; iDistanceToReissueOrder='..iDistanceToReissueOrder..'; bAddToExistingQueue='..tostring(bAddToExistingQueue or false)..'; sOptionalOrderDesc='..(sOptionalOrderDesc or 'nil')..'; bOverrideMicroOrder='..tostring(bOverrideMicroOrder or false)..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)) end
        if not(tLastOrder and tLastOrder[subrefiOrderType] == refiOrderIssueMove and ((iDistanceToReissueOrder or 0) == 0 or (iDistanceToReissueOrder and AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLastOrder[subreftOrderPosition]) < iDistanceToReissueOrder))) then
            if (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]))  then
                local bChangedViaNavigator
                if not(bAddToExistingQueue) then
                    if tLastOrder[subrefiOrderType] == refiOrderIssueMove and oUnit.GetNavigator and oUnit[refiOrderCount] <= 1 then
                        local oNavigator = oUnit:GetNavigator()
                        if oNavigator then
                            local tCurNavigatorTarget = oNavigator:GetCurrentTargetPos()
                            --if oUnit.UnitId == 'uec00011' and GetGameTimeSeconds() >= 360 then LOG('TEMPCODE Just got tCurNavigatorTarget='..repru(tCurNavigatorTarget)..'; Is unit state moving='..tostring(oUnit:IsUnitState('Moving'))..'; iDistanceToReissueOrder='..(iDistanceToReissueOrder or 'nil')..'; tLastOrder[subrefiOrderType]='..(tLastOrder[subrefiOrderType] or 'nil')) end
                            --Had a strange bug where a gunship would show as its last order being IssueMove based on tracking, be given a new navigator goal, but would stay in attack-move mode; although setgoal resulted in getcurrenttargetpos being updated straight away, by the next cycle it would've reset (but tracking on other orders for attackmove and attack yielded nothing); changing to only change navigator if unit state is moving fixed the problem
                            if tCurNavigatorTarget and AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[subreftOrderPosition], tCurNavigatorTarget) <= 3 and oUnit:IsUnitState('Moving') then
                                oNavigator:SetGoal(tOrderPosition)
                                bChangedViaNavigator = true
                                oUnit[reftiLastOrders] = {}
                                oUnit[refiOrderCount] = 0
                                --if oUnit.UnitId == 'uec00011' and GetGameTimeSeconds() >= 360 then LOG('TEMPCODE Just finished setting goal of navigator, cur navigator target='..repru(oNavigator:GetCurrentTargetPos())) end
                            end
                        end
                    end
                    if not(bChangedViaNavigator) then
                        IssueTrackedClearCommands(oUnit)
                    end
                end
                if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
                oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
                table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueMove, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
                if not(bChangedViaNavigator) then
                    IssueMove({oUnit}, tOrderPosition)
                end
                --[[if oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'uec00011' then
                    LOG('TEMPCODE Just sent issuemove order for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time '..GetGameTimeSeconds()..' to move to '..repru(tOrderPosition)..'; rMapPlayableArea='..repru(AiBotMap.rMapPlayableArea)..'; bChangedViaNavigator='..tostring(bChangedViaNavigator)..'; Dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tOrderPosition))
                    AiBotUtilities.DrawLocation(tOrderPosition, 3) --black; will cause desync
                end--]]
            else
                --We cant move here because weh ave active micro and dont want to override it
                oUnit[reftMoveDestinationIgnoredDueToMicro] = tOrderPosition
            end
        end
        if AiBotConfig.AiBotShowUnitNames and oUnit[reftiLastOrders][1] and (not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) or bOverrideMicroOrder) then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function IssueTrackedAggressiveMove(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --If we are close enough then issue the order again
        --if oUnit.UnitId == 'uaa0103' then AiBotUtilities.ErrorHandler('Tracked attack move audit trail targeting position X'..tOrderPosition[1]..'Z'..tOrderPosition[3], true, true) end
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end
        if not(tLastOrder and tLastOrder[subrefiOrderType] == refiOrderIssueAggressiveMove and iDistanceToReissueOrder and AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLastOrder[subreftOrderPosition]) < iDistanceToReissueOrder) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then
            local bChangedViaNavigator
            if not(bAddToExistingQueue) then
                if tLastOrder[subrefiOrderType] == refiOrderIssueAggressiveMove and oUnit.GetNavigator and oUnit[refiOrderCount] <= 1 then
                    local oNavigator = oUnit:GetNavigator()
                    if oNavigator then
                        local tCurNavigatorTarget = oNavigator:GetCurrentTargetPos()
                        if tCurNavigatorTarget and AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[subreftOrderPosition], tCurNavigatorTarget) <= 3 then
                            oNavigator:SetGoal(tOrderPosition)
                            bChangedViaNavigator = true
                            oUnit[reftiLastOrders] = {}
                            oUnit[refiOrderCount] = 0
                        end
                    end
                end
                if not(bChangedViaNavigator) then
                    IssueTrackedClearCommands(oUnit)
                end
            end

            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueAggressiveMove, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
            if not(bChangedViaNavigator) then
                IssueAggressiveMove({oUnit}, tOrderPosition)
            end
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function PatrolPath(oUnit, tPath, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder, bCheckIfStuck)
    --If the unit's last movement point isnt the first point in the path, then will reissue orders, with the path start point based on the estimated last path that it got to
    --bCheckIfStuck - put in due to issues where megalith would get stuck with valid orders for the AI; this will check if unit hasnt moved a while, and if so will reset its orders
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        local sFunctionRef = 'PatrolPath'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Last orders='..repru(oUnit[reftiLastOrders])..'; First point on path='..repru(tPath[1])..'; Will now refresh last orders') end
        UpdateRecordedOrders(oUnit)

        local tLastOrder
        if oUnit[reftiLastOrders] then tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]] end
        if bDebugMessages == true then LOG(sFunctionRef..': Unit orders after update='..repru(oUnit[reftiLastOrders])..'; Last order='..repru(tLastOrder)..'; Is the last order a move order='..tostring(tLastOrder[subrefiOrderType] == refiOrderIssueMove)..'; Last order position='..repru(tLastOrder[subreftOrderPosition])..'; tLastOrder pos 2 of table='..repru(tLastOrder[2])..'; Dist between path1 nd last order position='..AiBotUtilities.GetDistanceBetweenPositions(tPath[1], (tLastOrder[subreftOrderPosition] or {0,0,0}))..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; oUnit[AiBotUnitInfo.refiPatrolStuckCount]='..(oUnit[AiBotUnitInfo.refiPatrolStuckCount] or 'nil')) end
        local bMoveNotAttackMove = (oUnit[AiBotUnitInfo.refiCombatRange] or 0) <= 0
        local iOrderType
        if bMoveNotAttackMove then iOrderType = refiOrderIssueMove else iOrderType = refiOrderIssueAggressiveMove end
        local bUnitIsStuck = false
        if bCheckIfStuck then
            if not(tLastOrder) or not(tLastOrder[subrefiOrderType] == iOrderType) or AiBotUtilities.IsTableEmpty(oUnit[reftiLastOrders][1][subreftOrderPosition]) then
                --Dont have orders so ignore stuck check
                if bDebugMessages == true then LOG(sFunctionRef..': Dont have correct orders so will get new ones') end
            else
                local iDistToCurTarget = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oUnit[reftiLastOrders][1][subreftOrderPosition])
                if bDebugMessages == true then LOG(sFunctionRef..': Unit dist to target='..iDistToCurTarget) end
                if iDistToCurTarget < 12 then --have had megalith stuck at a distance of 8.6
                    if iDistToCurTarget < 6 then
                        oUnit[AiBotUnitInfo.refiPatrolStuckCount] = (oUnit[AiBotUnitInfo.refiPatrolStuckCount] or 0) + 1
                    elseif iDistToCurTarget < 9 then
                        oUnit[AiBotUnitInfo.refiPatrolStuckCount] = (oUnit[AiBotUnitInfo.refiPatrolStuckCount] or 0) + 0.75
                    else
                        oUnit[AiBotUnitInfo.refiPatrolStuckCount] = (oUnit[AiBotUnitInfo.refiPatrolStuckCount] or 0) + 5
                    end
                    if oUnit[AiBotUnitInfo.refiPatrolStuckCount] >= 10 then
                        bUnitIsStuck = true
                        oUnit[AiBotUnitInfo.refiPatrolStuckCount] = 0
                    end
                else
                    oUnit[AiBotUnitInfo.refiPatrolStuckCount] = 0
                end
            end
        end

        if (not(tLastOrder) or bUnitIsStuck or not(tLastOrder[subrefiOrderType] == iOrderType) or AiBotUtilities.GetDistanceBetweenPositions(tPath[1], tLastOrder[subreftOrderPosition]) > 1) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then
            --Our last active order isn't to move to the first point in the path, so will be reissuing the path
            if bDebugMessages == true then LOG(sFunctionRef..'; Will reissue orders to move along the path based on the closest point') end




            --first decide on start point for the path - pick the point closest to the unit
            local iClosestDist = 10000
            local iClosestPathRef
            local iCurDist
            for iPathRef, tPosition in tPath do
                iCurDist = AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), tPosition)
                if iCurDist < iClosestDist then
                    iClosestDist = iCurDist
                    iClosestPathRef = iPathRef
                end
            end

            if bUnitIsStuck or not(bAddToExistingQueue) then
                IssueTrackedClearCommands(oUnit)
            end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end

            local iPathSize = table.getn(tPath)
            if bUnitIsStuck then
                if iClosestPathRef == iPathSize then iClosestPathRef = 1
                else iClosestPathRef = iClosestPathRef + 1
                end
            end
            for iPath = iClosestPathRef, table.getn(tPath) do
                local tOrderPosition = {tPath[iPath][1], tPath[iPath][2], tPath[iPath][3]}
                table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = iOrderType, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
                oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
                if bMoveNotAttackMove then
                    IssueMove({oUnit}, tOrderPosition)
                else
                    IssueAggressiveMove({oUnit}, tOrderPosition)
                end
            end
            --Make the unit go to the first point on the path as its last order, but adjust very slightly
            local tOrderPosition = {tPath[1][1], tPath[1][2], tPath[1][3]}
            --if bDebugMessages == true and true then tOrderPosition[1] = tOrderPosition[1] + 0.1 tOrderPosition[3] = tOrderPosition[3] + 0.1 end
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = iOrderType, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            if bMoveNotAttackMove then
                IssueMove({oUnit}, tOrderPosition)
            else
                IssueAggressiveMove({oUnit}, tOrderPosition)
            end
        elseif bDebugMessages == true then LOG(sFunctionRef..': Dont want to refresh unit patrol orders')
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function IssueTrackedAttackMove(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --If we are close enough then issue the order again
        local tLastOrder
        if oUnit[reftiLastOrders] then tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]] end
        if not(tLastOrder[subrefiOrderType] == refiOrderIssueAggressiveMove and iDistanceToReissueOrder and AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLastOrder[subreftOrderPosition]) < iDistanceToReissueOrder) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueAggressiveMove, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
            IssueAggressiveMove({oUnit}, tOrderPosition)
            --[[if oUnit.UnitId == 'xra0105' and GetGameTimeSeconds() >= 360 then
                LOG('TEMPCODE Just sent AggressiveMove order for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time '..GetGameTimeSeconds()..' to move to '..repru(tOrderPosition)..'; rMapPlayableArea='..repru(AiBotMap.rMapPlayableArea))
                AiBotUtilities.DrawLocation(tOrderPosition)
            end--]]
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function IssueTrackedAttack(oUnit, oOrderTarget, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        --if oUnit.UnitId == 'uaa0103' then AiBotUtilities.ErrorHandler('Tracked attack audit trail targeting unit '..oOrderTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOrderTarget), true, true) end
        UpdateRecordedOrders(oUnit)
        --Issue order if we arent already trying to attack them
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end


        if not(tLastOrder[subrefiOrderType] == refiOrderIssueAttack and oOrderTarget == tLastOrder[subrefoOrderUnitTarget]) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueAttack, [subrefoOrderUnitTarget] = oOrderTarget})
            IssueAttack({oUnit}, oOrderTarget)
            --if oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'xra01051' and GetGameTimeSeconds() >= 360 then LOG('TEMPCODE Just issued attack order on oOrderTarget='..oOrderTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOrderTarget)) end
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

