                    end
                end
            end--]]
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderOvercharge, [subrefoOrderUnitTarget] = oOrderTarget})
            IssueOverCharge({oUnit}, oOrderTarget)
            --if oUnit[AiBotUnitInfo.refiFailedOCCount] then oUnit[AiBotUnitInfo.refiFailedOCCount] = 0 end
        else --OC - add to queue if we think we are already overcharging, as in some cases we dont
            --[[if AiBotUtilities.bQuietModActive and tLastOrder[subrefiOrderType] == refiOrderOvercharge and oOrderTarget == tLastOrder[subrefoOrderUnitTarget] and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oOrderTarget:GetPosition())  < oUnit[AiBotUnitInfo.refiDFRange] - 1 and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiLastWeaponEvent] or 0) < 1 and GetGameTimeSeconds() - (oUnit[AiBotUnitInfo.refiTimeOfLastOverchargeShot] or 0) >= 7 then
                oUnit[AiBotUnitInfo.refiFailedOCCount] = (oUnit[AiBotUnitInfo.refiFailedOCCount] or 0) + 1
                AiBotUtilities.DelayChangeVariable(oUnit, AiBotUnitInfo.refiFailedOCCount, -1, 5, nil, nil, 0, nil, true)--]]
            --elseif....
