function IssueTrackedMoveAndBuild(oUnit, tBuildLocation, sOrderBlueprint, tMoveTarget, iDistanceToReorderMoveTarget, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        if bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
            UpdateRecordedOrders(oUnit)
            local bDontAlreadyHaveOrder = true
            local iLastOrderCount = 0
            if oUnit[reftiLastOrders] then
                iLastOrderCount = oUnit[refiOrderCount]
                if iLastOrderCount >= 2 then
                    local tLastOrder = oUnit[reftiLastOrders][iLastOrderCount]
                    if tLastOrder[subrefiOrderType] == refiOrderIssueBuild and sOrderBlueprint == tLastOrder[subrefsOrderBlueprint] and AiBotUtilities.GetDistanceBetweenPositions(tBuildLocation, tLastOrder[subreftOrderPosition]) <= 0.5 then
                        local tSecondLastOrder = oUnit[reftiLastOrders][iLastOrderCount - 1]
                        if tSecondLastOrder[subrefiOrderType] == refiOrderIssueMove and AiBotUtilities.GetDistanceBetweenPositions(tMoveTarget, tSecondLastOrder[subreftOrderPosition]) < (iDistanceToReorderMoveTarget or 0.01) then
                            bDontAlreadyHaveOrder = false
                        end
                    end
                end
            end
            --if oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'uel01013' then LOG('IssueTrackedMoveAndBuild: oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bDontAlreadyHaveOrder='..tostring(bDontAlreadyHaveOrder or false)) end
            if bDontAlreadyHaveOrder then
                if not(bAddToExistingQueue) then
                    --LOG('IssueTrackedMoveAndBuild: Will clear commands of the unit')
                    oUnit[refiMoveAndBuildStuckCount] = (oUnit[refiMoveAndBuildStuckCount] or 0) + 1 --See also AiBotConditions.refiEngineerStuckCheckCount
                    IssueTrackedClearCommands(oUnit)
                end
                if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
                oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
                table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueMove, [subreftOrderPosition] = {tMoveTarget[1], tMoveTarget[2], tMoveTarget[3]}})
                IssueMove({oUnit}, tMoveTarget)

                oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
                table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueBuild, [subrefsOrderBlueprint] = sOrderBlueprint, [subreftOrderPosition] = {tBuildLocation[1], tBuildLocation[2], tBuildLocation[3]}})
                IssueBuildMobile({ oUnit }, tBuildLocation, sOrderBlueprint, {})
                if sOrderBlueprint then
                    AiBotEngineer.TrackQueuedBuilding(oUnit, sOrderBlueprint, tBuildLocation) --Cant do via fork thread or if are giving orders to 2 engineers at once they wont realise the location is queued
                else
                    AiBotUtilities.ErrorHandler('Attempted to build something with no blueprint')
                end
                if (oUnit[refiMoveAndBuildStuckCount] or 0) >= 5 and not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
                    local AiBotMicro = import('/lua/AiBot/AI/AiBotMicro.lua')
                    AiBotMicro.TrackTemporaryUnitMicro(oUnit, 30 + (oUnit[refiMoveAndBuildStuckCount] - 5)*10)
                end
                --[[if oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'ual02087' and oUnit:GetAIBrain():GetArmyIndex() == 3 then
                    LOG('Just sent a move and then build order to unit ual02087 at time '..GetGameTimeSeconds())
                end--]]
            end
            if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
        end
    end
end

function IssueTrackedBuild(oUnit, tOrderPosition, sOrderBlueprint, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        if bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) then
            UpdateRecordedOrders(oUnit)
            local tLastOrder

            if oUnit[reftiLastOrders] then
                if bAddToExistingQueue then
                    tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
                else tLastOrder = oUnit[reftiLastOrders][1]
                end
            end
            if not(tLastOrder[subrefiOrderType] == refiOrderIssueBuild and sOrderBlueprint == tLastOrder[subrefsOrderBlueprint] and AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLastOrder[subreftOrderPosition]) <= 0.5) then
                if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
                if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
                oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
                table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueBuild, [subrefsOrderBlueprint] = sOrderBlueprint, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
                IssueBuildMobile({ oUnit }, tOrderPosition, sOrderBlueprint, {})
                if sOrderBlueprint then
                    AiBotEngineer.TrackQueuedBuilding(oUnit, sOrderBlueprint, tOrderPosition) --Cnat do via fork thread or else engineers given orders in same cycle wont realise it's queued
                else
                    AiBotUtilities.ErrorHandler('Attempted to give a construction order to unit with no order blueprint')
                end
                --[[if oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'ual02087' and oUnit:GetAIBrain():GetArmyIndex() == 3 then
                    LOG('Just sent a build order to unit ual02087 at time '..GetGameTimeSeconds())
                end--]]
            end
            if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
        end
    end
end

