function IssueTrackedReclaim(oUnit, oOrderTarget, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder, bForceReissueOfOrderSubjectToMicro)
    local oUnitBrain = oUnit and oUnit.GetAIBrain and oUnit:GetAIBrain()
    local bDualGapAirEcoRole = oUnitBrain and (oUnitBrain.AiBotDualGapRole == 'top_air'
            or oUnitBrain.AiBotDualGapRole == 'bottom_air'
            or oUnitBrain.AiBotDualGapRole == 'eco')
    if bDualGapAirEcoRole
            and EntityCategoryContains(AiBotUnitInfo.refCategoryEngineer - categories.TECH1, oUnit.UnitId) then
        return false
    end
    if IsDestroyed(oOrderTarget) then
        AiBotUtilities.ErrorHandler('Tried giving reclaim order to a destroyed target', true)
    elseif bDontConsiderCombinedArmy or (oUnit.AiBotActive and (oOrderTarget.AiBotActive or not(oOrderTarget.GetAIBrain) or not(oOrderTarget:GetAIBrain() == oUnit:GetAIBrain()))) then
        UpdateRecordedOrders(oUnit)
        --Issue order if we arent already trying to attack them
        local tLastOrder



        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end
        --if GetGameTimeSeconds() >= 4*60+30 and oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'url01059' then LOG('TEMPCODE Tracked reclaim: is last order unit target nil='..tostring(tLastOrder[subrefoOrderUnitTarget] == nil)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; tLastOrder[subrefiOrderType]='..(tLastOrder[subrefiOrderType] or 'nil')..'; Is last order target equal to oOrderTarget='..tostring(oOrderTarget == tLastOrder[subrefoOrderUnitTarget])..'; oOrderTarget.CachePosition='..repru(oOrderTarget.CachePosition)..'; oLastOrderTarget cacheposition='..repru(tLastOrder[subrefoOrderUnitTarget].CachePosition)..'; First part of condition='..tostring((not(tLastOrder[subrefiOrderType] == refiOrderIssueReclaim and oOrderTarget == tLastOrder[subrefoOrderUnitTarget])))..'; Second part of condition='..tostring((not(oUnit:IsUnitState('Reclaiming')) and (not(oOrderTarget) or (oOrderTarget.GetPosition and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oOrderTarget:GetPosition()) <= (oUnit:GetBlueprint().Economy.MaxBuildDistance or 5)) or (not(oOrderTarget.GetPosition) and oOrderTarget.CachePosition and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oOrderTarget.CachePosition) <= (oUnit:GetBlueprint().Economy.MaxBuildDistance or 5)))))) end
        if (bForceReissueOfOrderSubjectToMicro or (not(tLastOrder[subrefiOrderType] == refiOrderIssueReclaim and oOrderTarget == tLastOrder[subrefoOrderUnitTarget]) or (not(oUnit:IsUnitState('Reclaiming')) and (not(oOrderTarget) or (oOrderTarget.GetPosition and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oOrderTarget:GetPosition()) <= (oUnit:GetBlueprint().Economy.MaxBuildDistance or 5)) or (not(oOrderTarget.GetPosition) and oOrderTarget.CachePosition and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oOrderTarget.CachePosition) <= (oUnit:GetBlueprint().Economy.MaxBuildDistance or 5)))))) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then

            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueReclaim, [subrefoOrderUnitTarget] = oOrderTarget})
            IssueReclaim({oUnit}, oOrderTarget)
            --if GetGameTimeSeconds() >= 4*60+30 and oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'url01059' then LOG('TEMPCODE just issued new reclaim order') end
            if not(oOrderTarget[AiBotEngineer.reftUnitsReclaimingUs]) then oOrderTarget[AiBotEngineer.reftUnitsReclaimingUs] = {} end
            table.insert(oOrderTarget[AiBotEngineer.reftUnitsReclaimingUs], oUnit)
            if not(oUnit[AiBotEngineer.reftUnitsWeAreReclaiming]) then oUnit[AiBotEngineer.reftUnitsWeAreReclaiming] = {} end
            table.insert(oUnit[AiBotEngineer.reftUnitsWeAreReclaiming], oOrderTarget)

        end
        if AiBotConfig.AiBotShowUnitNames and sOptionalOrderDesc then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc..(oOrderTarget.UnitId or '')) end
    end
end

function IssueTrackedGroundAttack(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder, oOptionalLinkedUnitTarget)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        --if oUnit.UnitId == 'uaa0103' then AiBotUtilities.ErrorHandler('Tracked attack ground audit trail targeting unit '..(oOptionalLinkedUnitTarget.UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOptionalLinkedUnitTarget) or 'nil')..'; tOrderPosition X'..tOrderPosition[1]..'Z'..tOrderPosition[3], true, true) end
        UpdateRecordedOrders(oUnit)
        --If we are close enough then issue the order again
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end

        if not(tLastOrder[subrefiOrderType] == refiOrderIssueGroundAttack and iDistanceToReissueOrder and AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLastOrder[subreftOrderPosition]) < iDistanceToReissueOrder) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then
            local bChangedViaNavigator
            if not(bAddToExistingQueue) then
                if tLastOrder[subrefiOrderType] == refiOrderIssueGroundAttack and oUnit.GetNavigator and oUnit[refiOrderCount] <= 1 then
                    local oNavigator = oUnit:GetNavigator()
                    if oNavigator then
                        local tCurNavigatorTarget = oNavigator:GetCurrentTargetPos()
                        if tCurNavigatorTarget and AiBotUtilities.GetDistanceBetweenPositions(tLastOrder[subreftOrderPosition], tCurNavigatorTarget) <= 3 then
                            oNavigator:SetGoal(tOrderPosition)
                            bChangedViaNavigator = true
                            oUnit[reftiLastOrders] = {}
                            oUnit[refiOrderCount] = 0
                        end
                    end
                end
                if not(bChangedViaNavigator) then
                    IssueTrackedClearCommands(oUnit)
                end
            end

            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueGroundAttack, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}, [subrefoOrderUnitTarget] = oOptionalLinkedUnitTarget})
            if not(bChangedViaNavigator) then
                IssueAttack({oUnit}, tOrderPosition)
            end

        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function IssueTrackedGuard(oUnit, oOrderTarget, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --Issue order if we arent already trying to attack them
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end
        if not(tLastOrder[subrefiOrderType] == refiOrderIssueGuard and oOrderTarget == tLastOrder[subrefoOrderUnitTarget]) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueGuard, [subrefoOrderUnitTarget] = oOrderTarget})
            if not(oOrderTarget[AiBotUnitInfo.reftoUnitsAssistingThis]) then oOrderTarget[AiBotUnitInfo.reftoUnitsAssistingThis] = {} end
            table.insert(oOrderTarget[AiBotUnitInfo.reftoUnitsAssistingThis], oUnit)
            IssueGuard({oUnit}, oOrderTarget)
            --LOG('Just told unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' to assists target '..oOrderTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOrderTarget))
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function IssueTrackedRepair(oUnit, oOrderTarget, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --Issue order if we arent already trying to attack them
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end
        local bIssueOrder = false
        if (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) and not(tLastOrder[subrefiOrderType] == refiOrderIssueRepair and oOrderTarget == tLastOrder[subrefoOrderUnitTarget]) then
            bIssueOrder = true
        elseif oOrderTarget:GetFractionComplete() < 1 and not(oUnit:IsUnitState('Repairing')) and not(oUnit:IsUnitState('Building')) then
            local iDistToTarget = AiBotUtilities.GetDistanceBetweenPositions(oOrderTarget:GetPosition(), oUnit:GetPosition())
            local oTargetBP = oOrderTarget:GetBlueprint()
            if iDistToTarget <= (oUnit:GetBlueprint().Economy.MaxBuildDistance or 0) + math.min((oTargetBP.Physics.SkirtSizeX or 0), (oTargetBP.Physics.SkirtSizeZ or 0)) then
                bIssueOrder = true
            end

        end
        if bIssueOrder then
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueRepair, [subrefoOrderUnitTarget] = oOrderTarget})

            IssueRepair({oUnit}, oOrderTarget)
            --Track against the unit we are repairing if it is under construction
            if oOrderTarget:GetFractionComplete() < 1 then
                if not(oOrderTarget[toUnitsOrderedToRepairThis]) then
                    oOrderTarget[toUnitsOrderedToRepairThis] = {}
                end
                table.insert(oOrderTarget[toUnitsOrderedToRepairThis], oUnit)
            end
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function IssueTrackedUpgrade(oUnit, sUpgradeRef, bAddToExistingQueue, sOptionalOrderDesc)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --Issue order if we arent already trying to attack them
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end
        if not(tLastOrder[subrefiOrderType] == refiOrderUpgrade and sUpgradeRef == tLastOrder[subrefsOrderBlueprint]) then
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderUpgrade, [subrefsOrderBlueprint] = sUpgradeRef})
            IssueUpgrade({oUnit}, sUpgradeRef)
            oUnit[AiBotUnitInfo.refbIssuedUpgrade] = true
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function DelayedUpgradeTracking(oUnit, sUpgradeRef)
    WaitTicks(2)
    if AiBotUnitInfo.IsUnitValid(oUnit) and oUnit:IsUnitState('Upgrading') then
        AiBotTeam.UpdateUpgradeTrackingOfUnit(oUnit, false, sUpgradeRef)
    end
end

function IssueTrackedEnhancement(oUnit, sUpgradeRef, bAddToExistingQueue, sOptionalOrderDesc)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        local sFunctionRef = 'IssueTrackedEnhancement'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        if bDebugMessages == true then
            LOG(sFunctionRef..': Start of code for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time='..GetGameTimeSeconds())
            if sUpgradeRef == 'AdvancedProduction' then LOG(sFunctionRef..': Getting advanced production, do we have ImprovedProduction='..tostring(oUnit:HasEnhancement('ImprovedProduction'))..'; do we have AdvancedProduction='..tostring(oUnit:HasEnhancement('AdvancedProduction'))..'; reftPreferredUpgrades='..repru(oUnit[import('/lua/AiBot/AI/AiBotACU.lua').reftPreferredUpgrades])) end
        end
        UpdateRecordedOrders(oUnit)
        --Issue order if we arent already trying to attack them
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end
        if not(tLastOrder[subrefiOrderType] == refiOrderEnhancement and sUpgradeRef == tLastOrder[subrefsOrderBlueprint]) and not(oUnit:IsUnitState('Upgrading')) and not(oUnit:IsUnitState('BeingUpgraded')) then
            --Do we have an existing enhancement that needs removing before we can get teh upgrade?
            local bApplySpecialMicroFlag = false
            if EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then AiBotTeam.tTeamData[oUnit:GetAIBrain().AiBotTeam][AiBotTeam.refiTimeLastIssuedACUEnhancementOrder] = GetGameTimeSeconds() end
            local sEnhancementOverride
            local tEnhancements = oUnit:GetBlueprint().Enhancements

            if AiBotUtilities.IsTableEmpty(tEnhancements) == false and (oUnit.HasEnhancement or oUnit.CreateEnhancement) then
                local tsUpgradeSlotUsed = {}
                local tbSlotInUse = {}
                local sSlotWanted
                local sPreReq
                if oUnit.HasEnhancement then
                    for sEnhancement, tEnhancementData in tEnhancements do
                        if bDebugMessages == true then LOG(sFunctionRef..': Does unit have sEnhancement='..sEnhancement..'='..tostring(oUnit:HasEnhancement(sEnhancement))) end
                        if oUnit:HasEnhancement(sEnhancement) then
                            tsUpgradeSlotUsed[sEnhancement] = tEnhancementData.Slot
                            tbSlotInUse[tEnhancementData.Slot] = true
                        elseif sEnhancement == sUpgradeRef then
                            sSlotWanted = tEnhancementData.Slot
                            sPreReq = tEnhancementData.Prerequisite
                        end
                    end
                end
                if bDebugMessages == true then LOG(sFunctionRef..': sSlotWanted='..(sSlotWanted or 'nil')..'; tbSlotInUse='..repru(tbSlotInUse)) end
                if sSlotWanted and tbSlotInUse[sSlotWanted] then
                    local bValidRemovalEnhancement
                    for sExistingEnhancement, sSlotUsed in tsUpgradeSlotUsed do
                        if bDebugMessages == true then LOG(sFunctionRef..': sExistingEnhancement='..sExistingEnhancement..'; sSlotUsed='..sSlotUsed) end
                        if sSlotUsed == sSlotWanted then
                            --Check if the existing enhancement is a prereq. of the desired enhancement
                            --Find the first upgrade that removes sEnhancement
                            if not(sPreReq) or not(sPreReq == sExistingEnhancement) then

                                if bDebugMessages == true then LOG(sFunctionRef..': Have an enhancement in the slot that we want, will search for its removal entry') end
                                for sEnhancement, tEnhancementData in tEnhancements do
                                    if bDebugMessages == true then LOG(sFunctionRef..': Is remove enhancements empty for sEnhancents='..tostring(tEnhancementData.RemoveEnhancements == nil)..'; sEnhancement='..sEnhancement..'; tEnhancementData.Slot='..(tEnhancementData.Slot or 'nil')..'; Prerequ='..(tEnhancementData.Prerequisite or 'nil')) end
                                    if tEnhancementData.Slot == sSlotWanted and tEnhancementData.RemoveEnhancements and (tEnhancementData.Prerequisite == nil or oUnit:HasEnhancement(tEnhancementData.Prerequisite)) then
                                        bValidRemovalEnhancement = false
                                        if bDebugMessages == true then LOG(sFunctionRef..': tEnhancementData.RemoveEnhancements='..repru(tEnhancementData.RemoveEnhancements)) end
                                        for iEntry, sRemovedEnhancement in tEnhancementData.RemoveEnhancements do
                                            if bDebugMessages == true then LOG(sFunctionRef..': Considering if sRemovedEnhancement '..sRemovedEnhancement..' equals sExistingEnhancement='..sExistingEnhancement) end
                                            if sRemovedEnhancement == sExistingEnhancement then
                                                --Do we have the rerequisite for this removal (since later upgrades can remove all in the chain)
                                                bValidRemovalEnhancement = true
                                                break
                                            end
                                        end
                                        if bDebugMessages == true then LOG(sFunctionRef..': bValidRemovalEnhancement='..tostring(bValidRemovalEnhancement)) end
                                        if bValidRemovalEnhancement then
                                            sEnhancementOverride = sEnhancement
                                            break
                                        end

                                    end

                                end
                                break
                            elseif sPreReq and sPreReq == sExistingEnhancement then
                                --Dont want to remove the enhancement
                                break
                            end
                        end
                    end
                end
            end
            --if oUnit.SetAutoOvercharge and EntityCategoryContains(categories.COMMAND, oUnit.UnitId) then oUnit:SetAutoOvercharge(true) end -After testing, although this owrked, the ACU wouldnt fire overcharge shots hwne upgrading for some reason
            if sEnhancementOverride then
                if bDebugMessages == true then LOG(sFunctionRef..': Will upgrade with sEnhancementOverride='..sEnhancementOverride) end
                if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
                if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
                oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
                table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderEnhancement, [subrefsOrderBlueprint] =sEnhancementOverride})
                IssueScript({oUnit}, {TaskName = 'EnhanceTask', Enhancement = sEnhancementOverride})
                AiBotTeam.UpdateUpgradeTrackingOfUnit(oUnit, false, sEnhancementOverride)
                oUnit[refiTimeOfLastRemovalUpgrade] = GetGameTimeSeconds()
            else
                if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
                if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
                oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
                table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderEnhancement, [subrefsOrderBlueprint] = sUpgradeRef})
                --LOG('About ot tell unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; owned by '..oUnit:GetAIBrain().Nickname..' to get enhancement upgrade '..sUpgradeRef..'; ACU upgrade count='..(oUnit[import('/lua/AiBot/AI/AiBotACU.lua').refiUpgradeCount] or 'nil'))
                IssueScript({oUnit}, {TaskName = 'EnhanceTask', Enhancement = sUpgradeRef})
                if bDebugMessages == true then LOG(sFunctionRef..': WIll ugprade unit with actual upgrade '..sUpgradeRef..'; just tried running issuescript for the unit') end
                AiBotTeam.UpdateUpgradeTrackingOfUnit(oUnit, false, sUpgradeRef)
                if oUnit[refiTimeOfLastRemovalUpgrade] and GetGameTimeSeconds() - oUnit[refiTimeOfLastRemovalUpgrade] <= 1 then
                    ForkThread(DelayedUpgradeTracking, oUnit, sUpgradeRef)
                end

                --Campaign specific - remove unit from platoon if it has one
                if AiBotMap.bIsCampaignMap and oUnit:GetAIBrain().CampaignAI then
                    local oExistingPlatoon = oUnit.PlatoonHandle
                    if bDebugMessages == true then LOG(sFunctionRef..': Considering if have existing platoon for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oExistingPlatoon is nil?='..tostring(oExistingPlatoon == nil)..'; Is getplan nil='..tostring(oExistingPlatoon.GetPlan == nil)) end
                    if oExistingPlatoon then
                        local AiBotOverseer = import('/lua/AiBot/AI/AiBotOverseer.lua')
                        ForkThread(AiBotOverseer.RemoveUnitsFromPlatoon, oExistingPlatoon, { oUnit }, false, nil)
                        if bDebugMessages == true then LOG(sFunctionRef..': Tried to remove unit from existing platoon') end
                    end
                end
            end

        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
        if bDebugMessages == true then LOG(sFunctionRef..': End of code for oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time='..GetGameTimeSeconds()) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function DestroyUnitAfterDelay(oUnit, iSecondsToWait)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        local sFunctionRef = 'DestroyUnitAfterDelay'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end


        WaitSeconds(1)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        if AiBotUnitInfo.IsUnitValid(oUnit) then

            if bDebugMessages == true then LOG(sFunctionRef..': Failed to kill unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' with unit state '..AiBotUnitInfo.GetUnitState(oUnit)) end
            oUnit:DestroyUnit(0)
        end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function IssueTrackedKillUnit(oUnit)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        if (not(oUnit[AiBotUnitInfo.refbCampaignTriggerAdded]) or not(AiBotMap.bIsCampaignMap)) then
            IssueTrackedClearCommands(oUnit)
            oUnit[refiOrderCount] = 1
            oUnit[reftiLastOrders] = {{[subrefiOrderType] = refiOrderKill}}
            if oUnit[AiBotUnitInfo.refbTriedToKill] then
                --Fork thread to try a dif method in 1s
                --ForkThread(DestroyUnitAfterDelay, oUnit, 1) --Disabled for now as the scneario where it happened (where I suspect it was engineers who were in a transport) didnt trigger after separate change, so not currently required
            else
                oUnit[AiBotUnitInfo.refbTriedToKill] = true
            end
            oUnit:Kill()
        end
    end
end

