function ClearAnyRepairingUnits(oUnitBeingRepaired)
    if bDontConsiderCombinedArmy or oUnitBeingRepaired.AiBotActive then
        --LOG('Is table of units ordered to repair oUnitBeingRepaired='..oUnitBeingRepaired.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnitBeingRepaired)..' empty='..tostring(AiBotUtilities.IsTableEmpty(oUnitBeingRepaired[toUnitsOrderedToRepairThis])))
        if oUnitBeingRepaired[toUnitsOrderedToRepairThis] then
            if AiBotUtilities.IsTableEmpty(oUnitBeingRepaired[toUnitsOrderedToRepairThis]) == false then
                for iUnit, oUnit in oUnitBeingRepaired[toUnitsOrderedToRepairThis] do
                    if AiBotUnitInfo.IsUnitValid(oUnit) then
                        --Is this unit still trying to repair this?
                        UpdateRecordedOrders(oUnit)
                        --LOG('Considering if oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' is still repairing; Last orders='..reprs(oUnit[reftiLastOrders]))
                        if oUnit[reftiLastOrders] then
                            local tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
                            if tLastOrder[subrefiOrderType] == refiOrderIssueRepair and oUnitBeingRepaired == tLastOrder[subrefoOrderUnitTarget] then
                                oUnit[reftiLastOrders] = nil --Clear here so we avoid the logic for lcearing in trackedclearcommands
                                IssueTrackedClearCommands(oUnit)
                            end

                        end
                    end
                end
            end
            oUnitBeingRepaired[toUnitsOrderedToRepairThis] = nil
        end
    end
end

function IssueTrackedRefuel(oUnit, oOrderTarget, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --Issue order if we arent already trying to attack them
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end


        if not(tLastOrder[subrefiOrderType] == refiOrderRefuel and oOrderTarget == tLastOrder[subrefoOrderUnitTarget]) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            --Moven ear the air staging first if are far away
            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oOrderTarget:GetPosition()) >= 125 then
                oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
                local tOrderPosition = oOrderTarget:GetPosition()
                table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueMove, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
                IssueMove({oUnit}, tOrderPosition)
            end

            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderRefuel, [subrefoOrderUnitTarget] = oOrderTarget})
            IssueTransportLoad({oUnit}, oOrderTarget)
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function ReleaseStoredUnits(oUnit, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive or UnitHasAiBotActiveCargo(oUnit) then
        --Use for air staging units
        UpdateRecordedOrders(oUnit)
        --Issue order if we arent already trying to attack them
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end


        if (not(tLastOrder[subrefiOrderType] == refiOrderReleaseStoredUnits) or GetGameTimeSeconds() - (oUnit[refiLastUnloadAttemptTime] or 0) >= 10) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then
            local tUnloadLocation = oUnit:GetPosition()
            local iXRand = math.random(0, 1)
            local iZRand = math.random(0, 1)
            if iXRand == 0 then iXRand = -1 end
            if iZRand == 0 then iZRand = -1 end
            tUnloadLocation[1] = tUnloadLocation[1] + 5 * iXRand
            tUnloadLocation[3] = tUnloadLocation[3] + 5 * iZRand
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderReleaseStoredUnits, [subreftOrderPosition] = tUnloadLocation})
            --Clear the cargo's orders
            local tCargo
            if oUnit.GetCargo then tCargo = oUnit:GetCargo() end
            IssueTransportUnload({ oUnit }, tUnloadLocation)
            if AiBotUtilities.IsTableEmpty(tCargo) == false then
                for iCargo, oCargo in tCargo do
                    IssueTrackedClearCommands(oCargo)
                end
            end
            oUnit[refiLastUnloadAttemptTime] = GetGameTimeSeconds()

        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function UnitHasAiBotActiveCargo(oUnit)
    --Intended for air staging buildings so they release AiBot units (although will also apply to other units such as transports)
    if oUnit.GetCargo then
        local tCargo = oUnit:GetCargo()
        if AiBotUtilities.IsTableEmpty(tCargo) == false then
            for iCargo, oCargo in tCargo do
                if oCargo.AiBotActive then
                    return true
                end
            end
        end
    end
end

function IssueTrackedTransportUnload(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --If we are close enough then issue the order again - consider the first order given if not to add to existing queue
        local tLastOrder

        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end
        --LOG('Considering issuing new unload order, Last order type='..(tLastOrder[subrefiOrderType] or 'nil')..'; iDistanceToReissueOrder='..(iDistanceToReissueOrder or 'nil')..'; Dist between positions='..AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, (tLastOrder[subreftOrderPosition] or {-100,0,-100}))..'; bOverrideMicroOrder='..tostring(bOverrideMicroOrder or false)..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; bAddToExistingQueue='..tostring(bAddToExistingQueue or false))
        if not(tLastOrder and tLastOrder[subrefiOrderType] == refiOrderUnloadTransport and iDistanceToReissueOrder and AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLastOrder[subreftOrderPosition]) < iDistanceToReissueOrder) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]))  then
            if not(bAddToExistingQueue) then
                IssueTrackedClearCommands(oUnit)
            end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderUnloadTransport, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
            IssueTransportUnload({oUnit}, tOrderPosition)
            --LOG('Given transport unload order for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..';  oUnit[AiBotAir.refiTargetZoneForDrop]='..( oUnit[AiBotAir.refiTargetZoneForDrop] or 'nil')..'; Unit owner='..oUnit:GetAIBrain().Nickname..'; Audit trail') AiBotUtilities.ErrorHandler('Audit trail', true, true)
            if EntityCategoryContains(AiBotUnitInfo.refCategoryTransport, oUnit.UnitId) and oUnit[AiBotAir.refiTargetZoneForDrop] and oUnit:GetAIBrain().AiBotAI then
                local iPlateauOrZero, iLandOrWaterZone = AiBotMap.GetClosestPlateauOrZeroAndZoneToPosition(tOrderPosition)
                local tLZOrWZData, tLZOrWZTeamData
                if (iLandOrWaterZone or 0) > 0 then
                    local iTeam = oUnit:GetAIBrain().AiBotTeam
                    local iAirSubteam = oUnit:GetAIBrain().AiBotAirSubteam
                    if iPlateauOrZero == 0 then
                        --Water zone
                        tLZOrWZData = AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone], AiBotMap.tPondDetails[AiBotMap.tiPondByWaterZone[iLandOrWaterZone]][AiBotMap.subrefPondWaterZones][iLandOrWaterZone]
                        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefWZTeamData][iTeam]
                    else
                        tLZOrWZData = AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone], AiBotMap.tAllPlateaus[iPlateauOrZero][AiBotMap.subrefPlateauLandZones][iLandOrWaterZone]
                        tLZOrWZTeamData = tLZOrWZData[AiBotMap.subrefLZTeamData][iTeam]
                    end
                    tLZOrWZTeamData[AiBotMap.refiTransportRecentUnloadCount] = (tLZOrWZTeamData[AiBotMap.refiTransportRecentUnloadCount] or 0) + 1
                    if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][iPlateauOrZero]) then
                        if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone] = {} end
                        AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][iPlateauOrZero] = {}
                    end
                    AiBotTeam.tTeamData[iTeam][AiBotTeam.reftiLastTransportDropByPlateauAndZone][iPlateauOrZero][iLandOrWaterZone] = GetGameTimeSeconds()
                    --LOG('Just recorded a drop order for iAirSubteam='..iAirSubteam..'; iPlateauOrZero='..iPlateauOrZero..'; iLandOrWaterZone='..iLandOrWaterZone..'; Time='..GetGameTimeSeconds())
                    AiBotUtilities.DelayChangeVariable(tLZOrWZTeamData, AiBotMap.refiTransportRecentUnloadCount, -1, 600, nil, nil, nil, nil, true)
                end
            end
        end
        if AiBotConfig.AiBotShowUnitNames and oUnit[reftiLastOrders][1] and (not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) or bOverrideMicroOrder) then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function DelayedTransportReloadCheck(oUnit, oOrderTarget)
    --Intended as a backup for cases where the engineer is given a load order but the transport doesnt load it
    --Ended up abandoning this as it didnt solve the issue and causes other issues
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        local sFunctionRef = 'DelayedTransportReloadCheck'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        local tTransportPositionAtStart = {oOrderTarget:GetPosition()[1], oOrderTarget:GetPosition()[2], oOrderTarget:GetPosition()[3]}
        local tUnitPositionAtStart = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}


        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
        WaitSeconds(5)
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
        function AreUnitsStillValidAndNotClose(tLastUnitPosition)
            if AiBotUnitInfo.IsUnitValid(oUnit) and AiBotUnitInfo.IsUnitValid(oOrderTarget) and not(oUnit:IsUnitState('Attached')) and oUnit[AiBotEngineer.refiAssignedAction] == AiBotEngineer.refActionLoadOntoTransport and oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad] == oUnit and AiBotUtilities.GetRoughDistanceBetweenPositions(oUnit:GetPosition(), oOrderTarget:GetPosition()) >= 4 and AiBotUtilities.GetRoughDistanceBetweenPositions(oUnit:GetPosition(), tLastUnitPosition) <= 1 then
                return true
            end
            return false
        end
        local iTotalLoopWait = 0
        local bSuspectedFailedLoad = false
        while AreUnitsStillValidAndNotClose(tUnitPositionAtStart) do
            tUnitPositionAtStart = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
            WaitSeconds(1)
            AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)
            iTotalLoopWait = iTotalLoopWait + 1
            if iTotalLoopWait >= 5 then
                if bDebugMessages == true then LOG(sFunctionRef..': iTotalLoopWait='..iTotalLoopWait..'; Transport position='..repru(oOrderTarget:GetPosition())) end
                if oOrderTarget:GetPosition()[2] - GetSurfaceHeight(oOrderTarget:GetPosition()[1], oOrderTarget:GetPosition()[3]) <= 1 then
                    bSuspectedFailedLoad = true
                    break
                end
            end
        end
        if bDebugMessages == true then LOG(sFunctionRef..': bSuspectedFailedLoad='..tostring(bSuspectedFailedLoad or false)) end
        if bSuspectedFailedLoad and AiBotUnitInfo.IsUnitValid(oOrderTarget) then
            --Warp to the transport then retry
            local tWarpLocation = oOrderTarget:GetPosition()
            if GetTerrainHeight(tWarpLocation[1], tWarpLocation[3]) >= AiBotMap.iMapWaterHeight or EntityCategoryContains(categories.HOVER + AiBotUnitInfo.refCategoryAmphibious, oUnit.UnitId) then
                tWarpLocation[2] = GetSurfaceHeight(tWarpLocation[1], tWarpLocation[3])
                Warp(oUnit, tWarpLocation, oUnit:GetOrientation())
                IssueTrackedTransportLoad(oUnit, oOrderTarget, false, 'BackupTL', true, true)
            end
        end

        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end

function IssueTrackedTransportLoad(oUnit, oOrderTarget, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder, bDontTryBackup)
    --oOrderTarget is the transport
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        local sFunctionRef = 'IssueTrackedTransportLoad'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)



        --[[if oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit) == 'url01058' then--and oUnit:GetAIBrain():GetArmyIndex() == 2 then
            LOG('IssueTrackedTransportLoad for unit'..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..' at time '..GetGameTimeSeconds())
            AiBotUtilities.ErrorHandler('Audit trail', true, true)
        end--]]

        --If the transport already has a unit told to load onto it, then this sends the assigned unit to move to that unit's position, and then to queue up the transport load order
        local bMoveIntoPositionInstead = false
        --local bDontUpdateUnitBeingLoaded = false
        if bDebugMessages == true then LOG(sFunctionRef..': oUnit='..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; oOrderTarget='..oOrderTarget.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOrderTarget)..'; Dist to target='..AiBotUtilities.GetDistanceBetweenPositions(oOrderTarget:GetPosition(), oUnit:GetPosition())..'; oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad]='..(oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad].UnitId or 'nil')..(AiBotUnitInfo.GetUnitLifetimeCount(oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad]) or 'nil')) end
        if not(oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad] == oUnit) and AiBotUnitInfo.IsUnitValid(oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad]) and not(oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad]:IsUnitState('Attached')) then
            --If already have an engineer/other unit trying to move here that is valid, then want to move to this engineer then queue up a transport order
            if bDebugMessages == true then LOG('Already have an engineer as the first transport load target='..oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad].UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad])..'; Unit state='..AiBotUnitInfo.GetUnitState(oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad])) end
            if AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oOrderTarget:GetPosition()) >= 5 then
                if bDebugMessages == true then LOG(sFunctionRef..': Are fairly close to transport, will move engineer towards transport so it is ready to be loaded') end
                IssueTrackedMove(oUnit, oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad]:GetPosition(), 3, bAddToExistingQueue, sOptionalOrderDesc..'Mov', bOverrideMicroOrder)
                bMoveIntoPositionInstead = true
                --else
                --bDontUpdateUnitBeingLoaded = true
            end

            --Issue - if try and continue with queuing up a transport load order, it results in the engineers and transport stuck, with engieners showing as having the order, but not moving
            --bAddToExistingQueue = true
        elseif not(oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad]) and AiBotUtilities.GetDistanceBetweenPositions(oUnit:GetPosition(), oOrderTarget:GetPosition()) > 12 then
            local NavUtils = AiBotUtilities.NavUtils
            local iHoverLabelWanted = NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, oUnit:GetPosition())
            if bDebugMessages == true then LOG(sFunctionRef..': iHoverLabelWanted='..(iHoverLabelWanted or 'nil')) end
            if iHoverLabelWanted then
                local tMoveTowardsTransportPosition
                local iAngleToTransport = AiBotUtilities.GetAngleFromAToB(oUnit:GetPosition(), oOrderTarget:GetPosition())

                for iCurDist = 14, 0, -2 do
                    if iCurDist == 0 then tMoveTowardsTransportPosition = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]} break
                    else
                        tMoveTowardsTransportPosition = AiBotUtilities.MoveInDirection(oUnit:GetPosition(), iAngleToTransport, iCurDist, true, false)
                        if bDebugMessages == true then LOG(sFunctionRef..': iCurDist='..iCurDist..'; tMoveTowardsTransportPosition='..repru(tMoveTowardsTransportPosition)..'; iAngleToTransport='..iAngleToTransport..'; iHoverLabelWanted='..iHoverLabelWanted..'; Terrain label='..NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeLand, tMoveTowardsTransportPosition)) end
                        if iHoverLabelWanted == NavUtils.GetTerrainLabel(AiBotMap.refPathingTypeHover, tMoveTowardsTransportPosition) then
                            break
                        end
                    end
                end
                IssueTrackedMove(oUnit, tMoveTowardsTransportPosition, 3, bAddToExistingQueue, sOptionalOrderDesc..'TMv', bOverrideMicroOrder)
                bMoveIntoPositionInstead = true
                if bDebugMessages == true then
                    LOG(sFunctionRef..': Are far away from transport so will move towards transport, tMoveTowardsTransportPosition='..repru(tMoveTowardsTransportPosition)..'; Unit position='..repru(oUnit:GetPosition())..'; Transport position='..repru(oOrderTarget:GetPosition()))
                    AiBotUtilities.DrawLocation(tMoveTowardsTransportPosition)
                end

            else
                UpdateRecordedOrders(oUnit)
            end
        else
            oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad] = nil
            UpdateRecordedOrders(oUnit)
        end

        if bDebugMessages == true then LOG(sFunctionRef..': Considering unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; bMoveIntoPositionInstead='..tostring(bMoveIntoPositionInstead or false)) end

        if not(bMoveIntoPositionInstead) then
            local tLastOrder
            if oUnit[reftiLastOrders] then
                if bAddToExistingQueue then
                    tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
                else tLastOrder = oUnit[reftiLastOrders][1]
                end
            end

            if bDebugMessages == true then LOG(sFunctionRef..': Unit last order='..reprs(tLastOrder)..'; tLastOrder[subrefiOrderType]='..(tLastOrder[subrefiOrderType] or 'nil')..'; Special micro active='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive] or false)..'; bOverrideMicroOrder='..tostring(bOverrideMicroOrder or false)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Transport state='..AiBotUnitInfo.GetUnitState(oOrderTarget)) end

            if bDontTryBackup or (not(tLastOrder[subrefiOrderType] == refiOrderLoadOntoTransport and oOrderTarget == tLastOrder[subrefoOrderUnitTarget]) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]))) or
                --Further redudnancy added v138 to try and combat another case where an engineer was stuck trying to load onto a transport from 7 dist away; the transport unit state showed as blank, the engi state showed as loading, and the transport would just bob up and down for minutes
                (oUnit[AiBotAir.refiTimeLastGivenOrderToLoadOntoTransport] and tLastOrder[subrefiOrderType] == refiOrderLoadOntoTransport and oOrderTarget == tLastOrder[subrefoOrderUnitTarget] and GetGameTimeSeconds() - oUnit[AiBotAir.refiTimeLastGivenOrderToLoadOntoTransport] >= 15 and AiBotUtilities.GetDistanceBetweenPositions(oOrderTarget:GetPosition(),oUnit:GetPosition()) >= 4 and AiBotUnitInfo.GetUnitState(oOrderTarget) == '' and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]))) then
                if not(bAddToExistingQueue) or AiBotUtilities.IsTableEmpty(   tLastOrder) then
                    --if not(bDontUpdateUnitBeingLoaded) then
                    IssueTrackedClearCommands(oOrderTarget) --Jip mentioned you can need to clear a transport's existing queue for a new load order to work
                    oOrderTarget[AiBotAir.refoTransportUnitTryingToLoad] = oUnit
                    if bDebugMessages == true then LOG(sFunctionRef..': Recording that transport is trying to load this unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end
                    --end
                end
                if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
                if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
                oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
                table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderLoadOntoTransport, [subrefoOrderUnitTarget] = oOrderTarget})
                IssueTransportLoad({oUnit}, oOrderTarget)
                oOrderTarget[AiBotAir.refiTransportTimeSpentWaiting] = math.max(0, (oOrderTarget[AiBotAir.refiTransportTimeSpentWaiting] or 0) - 15)
                oUnit[AiBotAir.refiTimeLastGivenOrderToLoadOntoTransport] = GetGameTimeSeconds()
                if bDebugMessages == true then LOG(sFunctionRef..': Just sent transport load order') end
                if not(bDontTryBackup) then ForkThread(DelayedTransportReloadCheck, oUnit, oOrderTarget) end --Found this caused more problems than it solved when it  just reissued the order; however per sprouto's suggestion warping the engineer first solves most issues where this happens; is on a 10s delay so should be slower than a human
                --Treat engi as having a high priority action now
                AiBotEngineer.TrackEngineerAction(oUnit, AiBotEngineer.refActionLoadOntoTransport, false, 1)
                oUnit[import('/lua/AiBot/AI/AiBotConditions.lua').refiEngineerStuckCheckCount] = 0
            end
            if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
        end
    end
end

function IssueTrackedTMLMissileLaunch(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --Always reissue the TML order (in contrast to approach for other orders) unless unit is busy as we arent reissuing this order every second, and in some cases would end up with the TML not firing despite having a target

        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end

        local AiBotBuilding = import('/lua/AiBot/AI/AiBotBuilding.lua')

        if not(oUnit:IsUnitState('Busy')) or (not(tLastOrder[subrefiOrderType] == refiOrderIssueTMLMissile and iDistanceToReissueOrder and AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLastOrder[subreftOrderPosition]) < iDistanceToReissueOrder) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]))) then
            --LOG('About to issue TML launch for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Time='..GetGameTimeSeconds())
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueTMLMissile, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
            IssueTactical({oUnit}, tOrderPosition)

            oUnit[AiBotBuilding.reftActiveNukeTarget] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}
        end
        if oUnit.GetTacticalSiloAmmoCount then
            local iCurMissiles = oUnit:GetTacticalSiloAmmoCount()
            if (iCurMissiles or 0) >= 2 then
                --Reconsider launching a missile in 11s if we have 2+ missiles loaded (partial redundancy since firing a missile only causes the logic to trigger as a 1-off)
                --LOG('Forked consideration of launching missile Delay1')
                ForkThread(AiBotBuilding.DelayedConsiderLaunchingMissile, oUnit, 11)
            end
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function IssueTrackedNukeMissileLaunch(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --Always reissue the nuke order (in contrast to approach for other orders) unless unit is busy as we arent reissuing this order every second, and in some cases would end up with the TML not firing despite having a target

        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end

        local AiBotBuilding = import('/lua/AiBot/AI/AiBotBuilding.lua')
        --LOG('Dealing with unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; Last order='..reprs(tLastOrder)..'; oUnit[AiBotUnitInfo.refbSpecialMicroActive]='..tostring(oUnit[AiBotUnitInfo.refbSpecialMicroActive])..'; Dist to last order position='..AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, (tLastOrder[subreftOrderPosition] or {0,0,0})))
        if not(oUnit:IsUnitState('Busy')) or (not(tLastOrder[subrefiOrderType] == refiOrderIssueNukeMissile and iDistanceToReissueOrder and AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLastOrder[subreftOrderPosition]) < iDistanceToReissueOrder) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]))) then
            --LOG('About to issue nuke launch for unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)..'; Unit state='..AiBotUnitInfo.GetUnitState(oUnit)..'; bAddToExistingQueue='..tostring(bAddToExistingQueue)..'; Time='..GetGameTimeSeconds())
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
        end
        --Apply below in all cases to ensure we actually launch a missile (it ought to just result in orders being queued if we already had such an order)
        if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
        oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
        table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueNukeMissile, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})

        IssueNuke({oUnit}, tOrderPosition)
        oUnit[AiBotBuilding.refiTimeLastFiredMissile] = GetGameTimeSeconds()
        --LOG('Forked consideration of launching missile Delay2')
        ForkThread(AiBotBuilding.DelayedConsiderLaunchingMissile, oUnit, 10, true, true)

        oUnit[AiBotBuilding.reftActiveNukeTarget] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}
        --Unpause incase we paused previously
        if oUnit[AiBotBuilding.refbPausedAsNoTargets] then
            oUnit[AiBotBuilding.refbPausedAsNoTargets] = false
            if AiBotUnitInfo.GetMissileCount(oUnit) <= 1 then
                --oUnit:SetAutoMode(true)
                AiBotUnitInfo.SetUnitMissileAutoBuildStatus(oUnit, true)
            end
            --oUnit:SetPaused(false)
            AiBotUnitInfo.PauseOrUnpauseUnitWithoutTracking(oUnit, false)
        end
        local iTeam = oUnit:GetAIBrain().AiBotTeam
        import('/lua/AiBot/AI/AiBotBuilding.lua').RecordNukeTarget(iTeam, tOrderPosition)
        --if not(AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations]) then AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations] = {} end
        --AiBotTeam.tTeamData[iTeam][AiBotTeam.subrefNukeLaunchLocations][math.floor(GetGameTimeSeconds())] = tOrderPosition

        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function IssueTrackedCapture(oUnit, oOrderTarget, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        UpdateRecordedOrders(oUnit)
        --Issue order if we arent already trying to attack them
        local tLastOrder
        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end


        if not(tLastOrder[subrefiOrderType] == refiOrderIssueCapture and oOrderTarget == tLastOrder[subrefoOrderUnitTarget]) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive])) then

            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueCapture, [subrefoOrderUnitTarget] = oOrderTarget})
            IssueCapture({oUnit}, oOrderTarget)
        end
        if AiBotConfig.AiBotShowUnitNames then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
    end
end

function IssueTrackedTeleport(oUnit, tOrderPosition, iDistanceToReissueOrder, bAddToExistingQueue, sOptionalOrderDesc, bOverrideMicroOrder)
    if bDontConsiderCombinedArmy or oUnit.AiBotActive then
        local sFunctionRef = 'IssueTrackedTeleport'
        local bDebugMessages = false if AiBotProfiler.bGlobalDebugOverride == true then   bDebugMessages = true end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerStart)

        UpdateRecordedOrders(oUnit)
        --If we are close enough then issue the order again - consider the first order given if not to add to existing queue
        local tLastOrder

        if oUnit[reftiLastOrders] then
            if bAddToExistingQueue then
                tLastOrder = oUnit[reftiLastOrders][oUnit[refiOrderCount]]
            else tLastOrder = oUnit[reftiLastOrders][1]
            end
        end
        --if EntityCategoryContains(categories.EXPERIMENTAL, oUnit.UnitId) then LOG('IssueTrackedMove: Time='..GetGameTimeSeconds()..'; reprs of tLastOrder='..reprs(tLastOrder)..'; tOrderPosition='..repru(tOrderPosition)..'; iDistanceToReissueOrder='..iDistanceToReissueOrder..'; bAddToExistingQueue='..tostring(bAddToExistingQueue or false)..'; sOptionalOrderDesc='..(sOptionalOrderDesc or 'nil')..'; bOverrideMicroOrder='..tostring(bOverrideMicroOrder or false)) end
        if bDebugMessages == true then LOG(sFunctionRef..': Near start, time='..GetGameTimeSeconds()..'; reprs of tLastOrder='..reprs(tLastOrder)..'; tOrderPosition='..repru(tOrderPosition)..'; iDistanceToReissueOrder='..iDistanceToReissueOrder..'; bAddToExistingQueue='..tostring(bAddToExistingQueue or false)..'; sOptionalOrderDesc='..(sOptionalOrderDesc or 'nil')..'; bOverrideMicroOrder='..tostring(bOverrideMicroOrder or false)) end
        if not(tLastOrder and tLastOrder[subrefiOrderType] == refiOrderIssueTeleport and iDistanceToReissueOrder and AiBotUtilities.GetDistanceBetweenPositions(tOrderPosition, tLastOrder[subreftOrderPosition]) < iDistanceToReissueOrder) and (bOverrideMicroOrder or not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]))  then
            if not(bAddToExistingQueue) then IssueTrackedClearCommands(oUnit) end
            if not(oUnit[reftiLastOrders]) then oUnit[reftiLastOrders] = {} oUnit[refiOrderCount] = 0 end
            oUnit[refiOrderCount] = oUnit[refiOrderCount] + 1
            table.insert(oUnit[reftiLastOrders], {[subrefiOrderType] = refiOrderIssueTeleport, [subreftOrderPosition] = {tOrderPosition[1], tOrderPosition[2], tOrderPosition[3]}})
            IssueTeleport({oUnit}, tOrderPosition)
            oUnit[AiBotUnitInfo.reftLastLocationWhenGaveTeleportOrder] = {oUnit:GetPosition()[1], oUnit:GetPosition()[2], oUnit:GetPosition()[3]}
            import('/lua/AiBot/AI/AiBotMicro.lua').TrackTemporaryUnitMicro(oUnit, 10) --Additional redundancy to reduce risk we cancel ACU orders while its teleporting
            if bDebugMessages == true then LOG(sFunctionRef..': Have given teleport order to unit '..oUnit.UnitId..AiBotUnitInfo.GetUnitLifetimeCount(oUnit)) end

        end
        if AiBotConfig.AiBotShowUnitNames and oUnit[reftiLastOrders][1] and (not(oUnit[AiBotUnitInfo.refbSpecialMicroActive]) or bOverrideMicroOrder) then UpdateUnitNameForOrder(oUnit, sOptionalOrderDesc) end
        AiBotProfiler.FunctionProfiler(sFunctionRef, AiBotProfiler.refProfilerEnd)
    end
end
